import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"6、【讼】 坎下乾上","description":"周易口诀义 - 6、【讼】 坎下乾上","frontmatter":{"title":"6、【讼】 坎下乾上","description":"周易口诀义 - 6、【讼】 坎下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/008.md","filePath":"zh/classics/koujueyi/008.md"}'),r={name:"zh/classics/koujueyi/008.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_6、【讼】-坎下乾上" tabindex="-1">6、【讼】 坎下乾上 <a class="header-anchor" href="#_6、【讼】-坎下乾上" aria-label="Permalink to “6、【讼】 坎下乾上”">​</a></h1><p>彖曰：讼，上刚下险，险而健，讼。「讼有孚窒惕，中吉」，刚来而得中也。「终凶」，讼不可成也。「利见大人」，尚中正也。「不利涉大川」，入于渊也。</p><p>象曰：天与水违行，讼。君子以作事谋始。</p><p>初六，不永所事，小有言，终吉。</p><p>象曰：「不永所事」，讼不可长也。虽「小有言」，其辩明也。</p><p>九二，不克讼，归而逋，其邑人三百户，无眚。</p><p>象曰：「不克讼」，归逋窜也。自下讼上，患至掇也。</p><p>六三，食旧德，贞厉，终吉。或从王事，无成。</p><p>象曰：「食旧德」，从上吉也。</p><p>九四，不克讼，复即命渝，安贞吉。</p><p>象曰：「复即命渝」，安贞不失也。</p><p>九五，讼，元吉。</p><p>象曰：「讼元吉」，以中正也。</p><p>上九，或锡之鞶带，终朝三禠之。</p><p>象曰：以讼受服，亦不足敬也。</p><p>解读</p><p>「讼有孚，窒惕，中吉，终凶」者，讼者，喧竞之名，乖争之义；窒，塞也；惕，惧也。凡为讼之体，必须信实，被人止塞，若能因此而怀惕惧，于中途而止，即获吉也。若终竟相讼，虽暂获胜而终必有凶，故曰「终凶」也。「利见大人」者，大人能断枉直，不失情理也。「不利涉大川」者，争讼之时，人心乖异，涉难济川，必见谋害，故周氏云：「与相争必被袭谋，当见坠于深渊也。」</p><p>象曰「天与水违行，讼，君子以作事谋始」者，天自西转，水乃东流，二体相违，故是「讼」也。君子兴为，必须谋虑其始，若初始分明，不相忤犯，讼无由生也。</p><p>「初六，不永所事，小有言，终吉」者，争讼之体，刚先犯弱，初六既是阴柔，不敢先讼九四，九四，先讼者也。往就辩答，道理分明，不被稽留，故「不永所事」，谓不永长为争讼之事也。</p><p>「九二，不克讼，归而逋，其邑人三百户，无眚」者，克，胜也；逋，逃也。九二体刚居阴，好为争讼之事，乃与九五相争也。以下讼上，以臣讼君，势不可敌，争讼如何得胜？故「不克讼」也。然讼既不胜，祸患必至，惧罪及身，遂将逃窜，窜归小邑，可免灾也；若其邑大人强，君疑不息，必被诛罚，故曰「三百户，乃无眚」也。</p><p>「六三，食旧德，贞厉，终吉。或从王事，无成」者，六三体柔弱，顺从上九，不敢有违，所有旧日之恩德，而不被黜夺，故曰「食旧德」也；然处两刚之间，情不相得，以贞自危，故曰「贞厉」也。体柔奉上，不敢为先，但须从上九之王事，不敢先成，故曰「或从王事，无成」也。</p><p>「九四：不克讼，复即命，渝，安贞吉」者，克，胜也；即，就也；复，反也。渝，变也。四体刚而「讼」初六，初对答，道理分明，四既不胜于初六，故曰「不克讼」也。若因此不胜，而能反就初六，悔过自新，即获安贞之吉，故曰「安贞吉」也。</p><p>九五「讼，元吉」者，余皆不当尊位，悉是争讼之人。九五体尊履正，即是断讼之主。刚即无所滞溺，中即心无偏曲，处位以斯，故获大吉，故曰「讼元吉」也。</p><p>上九：或锡之鞶带，终朝三褫之者，以刚处上，是讼而得胜，乃受鞶带之锡。然则不义而富，于我如浮云，以讼受荣，如何可保？故终一朝间，三被褫脱，不足敬也。因讼至锡，非德而受，故不足敬。旦至食时为朝。马云：「鞶带，大带衣也。」</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
